    st.markdown('<div class="panel-label">▥ MARKET OVERVIEW / 市場概覽</div>',unsafe_allow_html=True)
    a,b,c,d=st.columns(4)
    a.metric('股票快照數',f'{len(df):,}')
    b.metric('站上 MA20',f'{int((df.close>df.ma20).sum()):,}')
    c.metric('RSI 轉強',f'{int((df.rsi>df.rsi_prev).sum()):,}')
    d.metric('投信買超（有資料）',f'{int((df.trust_lots>0).sum()):,}')
    x,y=st.columns(2)
    with x:
        cats=['站上 MA20','低於/等於 MA20']
        vals=[int((df.close>df.ma20).sum()),int((df.close<=df.ma20).sum())]
        fig=go.Figure(go.Pie(labels=cats,values=vals,hole=.68,marker_colors=['#28c9a6','#df6574']))
        fig.update_layout(title='均線多空分布',height=350,template='plotly_dark',paper_bgcolor='#101a28',plot_bgcolor='#101a28',margin=dict(l=15,r=15,t=50,b=15))
        st.plotly_chart(fig,use_container_width=True,config={'displayModeBar':False})
    with y:
        rsi=pd.cut(df.rsi,bins=[-np.inf,30,50,70,np.inf],labels=['<30','30–50','50–70','>70']).value_counts().reindex(['<30','30–50','50–70','>70']).fillna(0)
        fig=go.Figure(go.Bar(x=rsi.index.astype(str),y=rsi.values,marker_color=['#df6574','#58758e','#28c9a6','#e5b85d']))
        fig.update_layout(title='RSI 區間分布',height=350,template='plotly_dark',paper_bgcolor='#101a28',plot_bgcolor='#101a28',margin=dict(l=15,r=15,t=50,b=15))
        st.plotly_chart(fig,use_container_width=True,config={'displayModeBar':False})

